fn options() -> ScanOptions {
    let mut settings = ScanOptions {
        samples: 1,
        discover: false,
        ..ScanOptions::default()
    };
    settings.network.no_proxy = true;
    settings
}

fn inspect(status: &str, headers: &str, body: &str, settings: ScanOptions) -> Value {
    let status = status.to_owned();
    let headers = headers.to_owned();
    let body = body.to_owned();
    let server = Server::new(move |_| response(&status, &headers, &body));
    let mut bounds = limits();
    bounds.max_body = 65_536;
    let report =
        serde_json::to_value(scan_configured(&server.url, bounds, &settings).unwrap()).unwrap();
    assert_eq!(server.paths.lock().unwrap().len(), settings.samples);
    report
}

fn laravel(report: &Value) -> Option<&Value> {
    report["technologies"]
        .as_array()
        .unwrap()
        .iter()
        .find(|t| t["name"] == "Laravel")
}

fn range<'a>(report: &'a Value, expected: &str) -> Option<&'a Value> {
    report["version_hypotheses"]
        .as_array()
        .unwrap()
        .iter()
        .find(|h| h["technology"] == "Laravel" && h["range"] == expected)
}

fn assert_no_exact_version(report: &Value) {
    assert!(report["version"].is_null());
    assert_eq!(report["version_candidates"], json!([]));
    assert_eq!(report["verdict"], "inconclusive");
    assert!(!report["analysis"]["certified"].as_bool().unwrap());
    if let Some(technology) = laravel(report) {
        assert_eq!(technology["versions"], json!([]));
    }
}

#[test]
fn default_welcome_generations_propose_conditional_families_without_exact_versions() {
    for (body, expected) in [
        (CLASSIC, ">=8,<10"),
        (TEN, "10.x"),
        (ELEVEN, "11.x"),
        (MODERN, ">=12,<14"),
    ] {
        let report = inspect("200 OK", "", body, options());
        let hypothesis =
            range(&report, expected).unwrap_or_else(|| panic!("missing {expected}: {report}"));
        assert_eq!(hypothesis["confidence"], "medium");
        assert!(!hypothesis["sources"].as_array().unwrap().is_empty());
        assert!(!hypothesis["references"].as_array().unwrap().is_empty());
        assert!(!hypothesis["limitations"].as_array().unwrap().is_empty());
        assert_eq!(report["runtime"]["status"], "inferred");
        assert_no_exact_version(&report);
    }
}

#[test]
fn the_thirteenth_generation_changelog_refines_the_shared_modern_welcome_pattern() {
    let report = inspect("200 OK", "", &format!("{MODERN}{THIRTEEN_LINK}"), options());
    range(&report, "13.x").expect("13.x changelog distinguishes the modern skeleton family");
    assert!(range(&report, ">=12,<14").is_none());
    assert_no_exact_version(&report);
}

#[test]
fn quoted_hidden_and_inert_welcome_examples_do_not_identify_the_running_framework() {
    for body in [
        format!("<article>{ELEVEN}</article>"),
        format!("<pre><code>{TEN}</code></pre>"),
        format!("<template>{MODERN}{THIRTEEN_LINK}</template>"),
        format!("<div hidden>{ELEVEN}</div>"),
        format!("<div aria-hidden=true>{MODERN}</div>"),
        format!("<!-- {CLASSIC} -->"),
        format!("<script>const example = `{MODERN}`;</script>"),
    ] {
        let report = inspect("200 OK", "", &body, options());
        assert!(laravel(&report).is_none(), "{body}: {report}");
        assert_eq!(report["version_hypotheses"], json!([]));
        assert_no_exact_version(&report);
    }
}

