#[test]
fn suppressing_hypotheses_keeps_the_template_observation_without_version_predictions() {
    let mut settings = options();
    settings.no_hypotheses = true;
    let report = inspect("200 OK", "", ELEVEN, settings);
    let framework = laravel(&report).expect("observed template remains identifiable");
    assert_eq!(framework["versions"], json!([]));
    assert_eq!(report["version_hypotheses"], json!([]));
    assert_eq!(report["runtime"]["status"], "unknown");
    assert!(
        framework["observations"]
            .as_array()
            .unwrap()
            .iter()
            .all(|o| o.get("hypothesis").is_none())
    );
}

#[test]
fn a_copied_older_template_cannot_override_an_explicit_newer_framework_declaration() {
    let report = inspect("200 OK", "X-Laravel-Version: 13.0.0\r\n", TEN, options());
    assert_eq!(laravel(&report).unwrap()["versions"], json!(["13.0.0"]));
    assert!(
        report["version_hypotheses"]
            .as_array()
            .unwrap()
            .iter()
            .all(|h| h["technology"] != "Laravel")
    );
    assert!(report["version"].is_null());
    assert_eq!(report["verdict"], "inconclusive");
}

