#[test]
fn real_error_renderer_headers_declare_versions_in_their_own_bounded_context() {
    for (body, laravel_version, php_patch) in
        [(MODERN_ERROR, "12.70.2", 26), (OLD_ERROR, "11.9.0", 1)]
    {
        let report = inspect("500 Internal Server Error", "", body, options());
        assert_eq!(
            laravel(&report).unwrap()["versions"],
            json!([laravel_version])
        );
        assert_eq!(report["version"]["patch"], php_patch);
        assert!(
            report["evidence"]
                .as_array()
                .unwrap()
                .iter()
                .all(|proof| proof["kind"] == "error_disclosure")
        );
        assert!(
            report["version_hypotheses"]
                .as_array()
                .unwrap()
                .iter()
                .all(|h| h["technology"] != "Laravel")
        );
        assert!(!report["analysis"]["certified"].as_bool().unwrap());
    }
}

