#[test]
fn modern_renderer_preserves_all_conflicting_sibling_versions_in_either_order() {
    for php_versions in [["8.4.26", "8.4.27"], ["8.4.27", "8.4.26"]] {
        let body = format!(
            "<h1>RuntimeException</h1><h3>Exception trace</h3>\
            <div><span>LARAVEL</span><span>12.70.2</span></div>\
            <div><span>LARAVEL</span><span>13.0.0</span></div>\
            <div><span>PHP</span><span>{}</span></div>\
            <div><span>PHP</span><span>{}</span></div>",
            php_versions[0], php_versions[1]
        );
        let report = inspect("500 Internal Server Error", "", &body, options());
        assert!(report["version"].is_null(), "{report}");
        assert_eq!(report["version_status"], "conflicting");
        let mut patches: Vec<_> = report["evidence"]
            .as_array()
            .unwrap()
            .iter()
            .map(|proof| proof["version"]["patch"].as_u64().unwrap())
            .collect();
        patches.sort_unstable();
        patches.dedup();
        assert_eq!(patches, vec![26, 27]);
        let mut versions: Vec<_> = laravel(&report).unwrap()["versions"]
            .as_array()
            .unwrap()
            .iter()
            .map(|v| v.as_str().unwrap())
            .collect();
        versions.sort_unstable();
        assert_eq!(versions, vec!["12.70.2", "13.0.0"]);
    }
}

