#[test]
fn mixed_renderer_generations_preserve_conflicting_evidence_in_either_dom_order() {
    let modern = MODERN_ERROR.replace("8.4.26", "8.4.27");
    let old = OLD_ERROR.replace("8.2.1", "8.4.26");
    for body in [format!("{modern}{old}"), format!("{old}{modern}")] {
        let report = inspect("500 Internal Server Error", "", &body, options());
        assert!(report["version"].is_null(), "{report}");
        assert_eq!(report["version_status"], "conflicting");
        assert_eq!(report["version_candidates"].as_array().unwrap().len(), 2);
        let framework = laravel(&report).unwrap();
        let mut versions: Vec<_> = framework["versions"]
            .as_array()
            .unwrap()
            .iter()
            .map(|version| version.as_str().unwrap())
            .collect();
        versions.sort_unstable();
        assert_eq!(versions, vec!["11.9.0", "12.70.2"]);
        assert!(
            report["version_hypotheses"]
                .as_array()
                .unwrap()
                .iter()
                .all(|hypothesis| hypothesis["technology"] != "Laravel")
        );
    }
}

#[test]
fn classic_welcome_footer_versions_need_visible_welcome_context_and_retain_conflicts() {
    let footer = "<div class=text-sm>Laravel v8.83.29 (PHP v8.4.26)</div>";
    let report = inspect("200 OK", "", &format!("{CLASSIC}{footer}"), options());
    assert_eq!(report["version"]["patch"], 26);
    assert_eq!(laravel(&report).unwrap()["versions"], json!(["8.83.29"]));
    assert!(range(&report, ">=8,<10").is_none());
    assert!(!report["analysis"]["certified"].as_bool().unwrap());
    let other = footer
        .replace("8.83.29", "9.52.21")
        .replace("8.4.26", "8.4.27");
    for body in [
        format!("{CLASSIC}{footer}{other}"),
        format!("{CLASSIC}{other}{footer}"),
    ] {
        let report = inspect("200 OK", "", &body, options());
        assert!(report["version"].is_null(), "{report}");
        assert_eq!(report["version_status"], "conflicting");
        assert_eq!(report["version_candidates"].as_array().unwrap().len(), 2);
        let versions = laravel(&report).unwrap()["versions"].as_array().unwrap();
        assert_eq!(versions.len(), 2);
        assert!(versions.contains(&json!("8.83.29")));
        assert!(versions.contains(&json!("9.52.21")));
    }
    for body in [
        CLASSIC.to_owned(),
        format!(
            "{CLASSIC}{}",
            footer
                .replace("8.83.29", "REDACTED")
                .replace("8.4.26", "REDACTED")
        ),
        footer.to_owned(),
        format!("<h1>Laravel documentation</h1>{footer}"),
        format!("{CLASSIC}<div hidden>{footer}</div>"),
        format!("{CLASSIC}<article>{footer}</article>"),
        format!("{CLASSIC}<pre><code>{footer}</code></pre>"),
    ] {
        assert_no_exact_version(&inspect("200 OK", "", &body, options()));
    }
}
